class Renders6(RootModel[Renders | Renders4 | Renders5]):
    root: Annotated[
        Renders | Renders4 | Renders5,
        Field(
            description='A single rendered piece of a creative preview with discriminated output format',
            discriminator='output_format',
            title='Preview Render',
        ),
    ]
    def __getattr__(self, name: str) -> Any:
        """Proxy attribute access to the wrapped type."""
        if name.startswith('_'):
            raise AttributeError(name)
        return getattr(self.root, name)

class Input3(AdCPBaseModel):
    model_config = ConfigDict(
        extra='allow',
    )
    name: Annotated[str, Field(description='Human-readable name for this preview')]
    macros: Annotated[
        dict[str, str] | None, Field(description='Macro values applied to this preview')
    ] = None
    context_description: Annotated[
        str | None, Field(description='Context description applied to this preview')
    ] = None


class Preview3(AdCPBaseModel):
    preview_id: Annotated[str, Field(description='Unique identifier for this preview')]
